/// Looks up a language table.
#[must_use]
pub fn lookup(lang: &str) -> Option<&'static [&'static str]> {
    match lang {
        "en" => Some(EN),
        "es" => Some(ES),
        "eu" => Some(EU),
        "fa" => Some(FA),
        "fi" => Some(FI),
        "fr" => Some(FR),
        "ga" => Some(GA),
        _ => None,
    }
}
